modernisierung_kappung_mit_laufenden_abzuegen <- function(jahresbetrag_vor_laufenden_abzuegen=NULL, jaehrliche_zinsermaessigung=NULL, jaehrliche_laufende_zuschuesse_und_darlehen=NULL, monatliche_restkappung=NULL, abzugsreihenfolge=NULL, methodennachweis=NULL) {
 jahr <- .geld(jahresbetrag_vor_laufenden_abzuegen);zins <- .geld(jaehrliche_zinsermaessigung);laufend <- .geld(jaehrliche_laufende_zuschuesse_und_darlehen);kap <- .geld(monatliche_restkappung)
 .auswahl(abzugsreihenfolge,'abzugsreihenfolge',c('abzug_vor_kappung','abzug_nach_kappung'));.text(methodennachweis,'methodennachweis')
 abzug <- .addieren(zins,laufend);zwischensaldo <- .subtrahieren(jahr,abzug)
 vor <- .dividieren(if(.vergleichen(zwischensaldo,.bruch(0))<0) .bruch(0) else zwischensaldo,.bruch(12));if(.vergleichen(vor,kap)>0) vor <- kap
 nach <- .dividieren(jahr,.bruch(12));if(.vergleichen(nach,kap)>0) nach <- kap
 nach <- .subtrahieren(nach,.dividieren(abzug,.bruch(12)));if(.vergleichen(nach,.bruch(0))<0) nach <- .bruch(0)
 monat <- if(abzugsreihenfolge=='abzug_vor_kappung') vor else nach
 wert <- list(jaehrliche_laufende_abzuege=.bruchteile(abzug),monatsbetrag_abzug_vor_kappung=.bruchteile(vor),monatsbetrag_abzug_nach_kappung=.bruchteile(nach),monatlicher_betrag_nach_vorgegebener_methode=.bruchteile(monat),jaehrlicher_betrag_nach_vorgegebener_methode=.bruchteile(.multiplizieren(monat,.bruch(12))),rechenweg=abzugsreihenfolge)
 eingaben <- list(jahresbetrag_vor_laufenden_abzuegen=jahresbetrag_vor_laufenden_abzuegen, jaehrliche_zinsermaessigung=jaehrliche_zinsermaessigung, jaehrliche_laufende_zuschuesse_und_darlehen=jaehrliche_laufende_zuschuesse_und_darlehen, monatliche_restkappung=monatliche_restkappung, abzugsreihenfolge=abzugsreihenfolge, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_MODERNISIERUNG_KAPPUNG_MIT_LAUFENDEN_ABZUEGEN",eingaben,list(list(operation="Beide arithmetischen Reihenfolgen j\u00e4hrlicher F\u00f6rderabz\u00fcge und monatlicher Kappung berechnen; Ergebnis nur gem\u00e4\u00df ausdr\u00fccklich rechtlich vorgegebener Methode ausw\u00e4hlen.")),eingaben)
 ergebnis$hinweise <- list("Bedingte Zahlenrechnung f\u00fcr das Zusammenwirken von\u00a7559IIIa und\u00a7559aII. Die allgemeine rechtliche Reihenfolge laufender F\u00f6rderabz\u00fcge gegen\u00fcber der Kappung ist in der Quellenarbeit nicht abschlie\u00dfend gekl\u00e4rt; diese Funktion entscheidet sie ausdr\u00fccklich nicht. Beide vollst\u00e4ndigen Rechenwege werden ausgewiesen, der ausgew\u00e4hlte nur gem\u00e4\u00df zwingender begr\u00fcndeter Nutzervorgabe. Vor Kappung: min(max(Jahresbetrag-Abz\u00fcge,0)/12,Restkappung). Nach Kappung: max(min(Jahresbetrag/12,Restkappung)-Abz\u00fcge/12,0). Null begrenzt nur den hier berechneten positiven Erh\u00f6hungsbetrag; keine automatische Senkung bisheriger Miete, F\u00f6rderungsauszahlung oder R\u00fcckforderung. Kostenbasis, zul\u00e4ssige F\u00f6rderpositionen, Einzelwohnungszuordnung, H\u00e4rte und Wirksamkeit separat. Keine erneute Anrechnung einmaliger Kostenbeitr\u00e4ge oder fr\u00fcherer Mieterh\u00f6hungen.")
 ergebnis
}
